        if (distPad < 0.25) {
          integralX = clamp(integralX + (pad.x - p.x) * dt, -0.3, 0.3);
          integralZ = clamp(integralZ + (pad.z - p.z) * dt, -0.3, 0.3);
        }

        if (phase === 'pad_align') {
          // Approach pad and lower altitude smoothly
          const approachY = clamp(0.18 + 0.65 * distPad, 0.18, 0.85);
          target = { x: pad.x, y: approachY, z: pad.z };
          if (distPad < 0.095 && speedHoriz < 0.28 && p.y < 0.32) {
            phase = 'descend';
          }
        }

        if (phase === 'descend') {
          target = { x: pad.x, y: 0.05, z: pad.z };
          kpY = 5.0; kdY = 4.2;
          if (distPad > 0.135 && p.y > 0.11) {
            phase = 'pad_align';
          } else if (p.y <= 0.092 && distPad <= 0.135 && Math.hypot(v.x, v.y, v.z) < 0.46) {
            phase = 'pin';
            pinned = true;
          }
        }

        if (phase === 'pin') {
          target = { x: pad.x, y: 0.0, z: pad.z };
          pinned = true;
          if (distPad > 0.145 && p.y > 0.10) {
            phase = 'pad_align';
            pinned = false;
          }
        }
      }

      // 4. Outer position control with wind & drag feedforward + gust braking
      const ex = target.x - p.x;
      const ey = target.y - p.y;
      const ez = target.z - p.z;

      integralY = clamp(integralY + ey * dt, -0.6, 0.8);

      // Extra damping when gusts are active ("brake gusts")
      const gustBrake = clamp(gustMag * 0.35, 0, 1.8);
      const axPd = kpX * ex + kdX * (targetVel.x - velFilt.x) - gustBrake * velFilt.x + 1.5 * integralX;
      const azPd = kpZ * ez + kdZ * (targetVel.z - velFilt.z) - gustBrake * velFilt.z + 2.2 * integralZ;
      const ayPd = kpY * ey - kdY * velFilt.y + 2.0 * integralY;

      // Total required thrust acceleration vector (tx, ty, tz) compensating wind and drag
      const tx = clamp(axPd - windFast.x + dragCoeff * velFilt.x, -6.5, 6.5);
      const tz = clamp(azPd - windFast.z + dragCoeff * velFilt.z, -6.5, 6.5);
      const ty = clamp(9.81 + ayPd + dragCoeff * velFilt.y, 2.5, 16.5);

      // Transform horizontal thrust acceleration to body frame
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bx = cy * tx - sy * tz;
      const bz = sy * tx + cy * tz;

      let maxTilt = 0.48;
      if (obs.gateIndex === 3 && p.y < 0.22) {
        maxTilt = p.y < 0.11 ? 0.14 : 0.26;
      }

      const desPitch = clamp(Math.atan2(bx, ty), -maxTilt, maxTilt);
      const desRoll = clamp(-Math.atan2(bz * Math.cos(att.pitch), ty), -maxTilt, maxTilt);

      let thrust;
      if (pinned) {
        // Pin pad with low thrust and small tilt (< 0.18 rad)
        thrust = 0.16;
      } else {
        const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
        thrust = clamp(ty / (thrustScale * cosTilt), 0.05, 1.0);
        if (obs.gateIndex === 3 && phase === 'descend' && p.y < 0.14) {
          // Soften vertical descent speed near floor
          const maxSink = -0.35;
          if (v.y < maxSink) {
            thrust = clamp(thrust + 0.25 * (maxSink - v.y), 0.05, 1.0);
          }
        }
      }

      // 5. Invert inner attitude loop with torque bias compensation
      const totalBiasRoll = biasPerThrust.roll * (0.7 * thrustLag + 0.3 * thrust) + fastBias.roll;
      const totalBiasPitch = biasPerThrust.pitch * (0.7 * thrustLag + 0.3 * thrust) + fastBias.pitch;
      const totalBiasYaw = biasPerThrust.yaw * (0.7 * thrustLag + 0.3 * thrust) + fastBias.yaw;

      const alphaDesRoll = 78 * (desRoll - att.roll) - 16 * rates.roll;
      const alphaDesPitch = 78 * (desPitch - att.pitch) - 16 * rates.pitch;

      const cmdRoll = clamp(
        att.roll + (alphaDesRoll + 13.4 * rates.roll - 22 * simIntegral.roll - totalBiasRoll) / 65,
        -0.6,
        0.6
      );
      const cmdPitch = clamp(
        att.pitch + (alphaDesPitch + 13.4 * rates.pitch - 22 * simIntegral.pitch - totalBiasPitch) / 65,
        -0.6,
        0.6
      );

      const desYawRate = -2.5 * att.yaw;
      const cmdYawRate = clamp(
        desYawRate + (0.4 * rates.yaw - totalBiasYaw) / 8,
        -2.0,
        2.0
      );

      prevPos = { x: p.x, y: p.y, z: p.z };
      prevVel = { x: v.x, y: v.y, z: v.z };
      prevAtt = { roll: att.roll, pitch: att.pitch, yaw: att.yaw };
      prevRates = { roll: rates.roll, pitch: rates.pitch, yaw: rates.yaw };
      lastAction = { thrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };

      return lastAction;
    },
  };
}

