          const updatedDrag = 0.02745 * thrustScale;
          const obsAx = (v.x - prevVel.x) / dt;
          const obsAz = (v.z - prevVel.z) / dt;
          const predAx = thrustScale * thrustLag * dirX - updatedDrag * (0.5 * (v.x + prevVel.x));
          const predAz = thrustScale * thrustLag * dirZ - updatedDrag * (0.5 * (v.z + prevVel.z));
          const instWindAx = clamp(obsAx - predAx, -12, 12);
          const instWindAz = clamp(obsAz - predAz, -12, 12);

          windFast.x += 0.25 * (instWindAx - windFast.x);
          windFast.z += 0.25 * (instWindAz - windFast.z);
          windMed.x += 0.10 * (instWindAx - windMed.x);
          windMed.z += 0.10 * (instWindAz - windMed.z);
          windSlow.x += 0.04 * (instWindAx - windSlow.x);
          windSlow.z += 0.04 * (instWindAz - windSlow.z);
        }
      }

      const dragCoeff = 0.02745 * thrustScale;
      // Lead-compensated wind estimate + transient gust detection
      const windLeadX = windFast.x + 0.35 * (windFast.x - windMed.x);
      const windLeadZ = windFast.z + 0.35 * (windFast.z - windMed.z);
      const gustTransX = windFast.x - windMed.x;
      const gustTransZ = windFast.z - windMed.z;
      const gustTransMag = Math.hypot(gustTransX, gustTransZ);

      // Current horizontal thrust acceleration to estimate uncompensated gust acceleration
      const curBodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const curBodyZ = -Math.sin(att.roll);
      const curDirX = Math.cos(att.yaw) * curBodyX + Math.sin(att.yaw) * curBodyZ;
      const curDirZ = -Math.sin(att.yaw) * curBodyX + Math.cos(att.yaw) * curBodyZ;
      const netAccX = thrustScale * thrustLag * curDirX - dragCoeff * velFilt.x + windFast.x;
      const netAccZ = thrustScale * thrustLag * curDirZ - dragCoeff * velFilt.z + windFast.z;

      let target = { x: 0, y: 1.0, z: 0 };
      let targetVel = { x: 0, y: 0, z: 0 };
      let kpX = 5.0, kdX = 3.8;
      let kpZ = 7.2, kdZ = 4.6;
      let kpY = 7.0, kdY = 4.4;

      if (obs.gateIndex < 3) {
        pinned = false;
        const gate = obs.nextGate.centre;
        if (targetGate !== obs.gateIndex) {
          targetGate = obs.gateIndex;
          phase = 'align';
          centeredCount = 0;
          integralZ = 0;
          integralX = 0;
        }

        const dxGate = gate.x - p.x;
        const dyGate = gate.y - p.y;
        const dzGate = gate.z - p.z;

        // Predict crossing position at x = gate.x
        const effVx = Math.max(0.55, velFilt.x + 0.5 * Math.max(0, netAccX) * 0.15);
        const tCross = clamp(dxGate / effVx, 0.02, 0.30);
        const zPred = p.z + velFilt.z * tCross + 0.35 * netAccZ * tCross * tCross;
        const yPred = p.y + velFilt.y * tCross;

        // Stopping distance in X if we need to abort lunge before crossing gate.x
        const aBrakeX = Math.max(1.6, 4.3 - Math.max(0, windFast.x));
        const stopDistX = (velFilt.x > 0 ? velFilt.x * 0.075 + (velFilt.x * velFilt.x) / (2 * aBrakeX) : 0) + 0.035;
        const canStopBeforeGate = dxGate > stopDistX;

        const zCentered = Math.abs(dzGate) < 0.019 && Math.abs(zPred - gate.z) < 0.022 && Math.abs(velFilt.z) < 0.13;
        const yCentered = Math.abs(dyGate) < 0.085 && Math.abs(yPred - gate.y) < 0.105 && Math.abs(velFilt.y) < 0.30;
        const xReady = dxGate > 0.05 && dxGate < 0.36 && velFilt.x > -0.25 && velFilt.x < 0.65;
