          } else {
            centeredCount = Math.max(0, centeredCount - 1);
          }

          const urgent = obs.t > 3.6 * (obs.gateIndex + 1) && Math.abs(dzGate) < 0.022 && Math.abs(zPred - gate.z) < 0.025 && Math.abs(dyGate) < 0.095 && dxGate > 0.04 && dxGate < 0.42;
