            targetVel.x = 1.65;
            kpX = 5.8;
            kdX = 3.5;
            kpZ = dxGate < 0.14 ? 12.5 : 9.5;
            kdZ = dxGate < 0.14 ? 6.0 : 5.2;
            kpY = 8.5;
            kdY = 4.8;
