        const distPad = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedHoriz = Math.hypot(velFilt.x, velFilt.z);
        const speedTotal = Math.hypot(v.x, v.y, v.z);

        if (targetGate !== 3) {
