          integralX = clamp(integralX + (pad.x - p.x) * dt, -0.25, 0.25);
          integralZ = clamp(integralZ + (pad.z - p.z) * dt, -0.25, 0.25);
        } else {
          integralX *= 0.95;
          integralZ *= 0.95;
        }

        if (phase === 'pad_glide') {
          // Diagonal glide directly down toward pad
