      const ey = target.y - p.y;
      const ez = target.z - p.z;

      const aSafeX = Math.max(1.3, 3.8 - Math.max(0, Math.sign(ex) * windFast.x));
      const aSafeZ = Math.max(1.3, 3.8 - Math.max(0, Math.sign(ez) * windFast.z));
