          const unsafeZ = Math.abs(dzGate) > 0.025 || Math.abs(zPred - gate.z) > 0.028;
          const unsafeY = Math.abs(dyGate) > 0.105 || Math.abs(yPred - gate.y) > 0.120;
          if (dxGate > 0.085 && (unsafeZ || unsafeY)) {
            phase = 'align';
            centeredCount = 0;
            target = { x: Math.min(p.x, gate.x - 0.22), y: gate.y, z: gate.z };
            kpX = 6.5;
            kdX = 5.0;
          } else {
            target = { x: gate.x + 0.36, y: gate.y, z: gate.z };
            targetVel.x = 1.50;
            kpX = 5.4;
            kdX = 3.5;
            kpZ = 8.8;
            kdZ = 5.3;
            kpY = 7.8;
            kdY = 4.6;
          }
        }
      } else {
        const pad = obs.pad.centre;
        const distPad = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedHoriz = Math.hypot(velFilt.x, velFilt.z);
        const speedTotal = Math.hypot(v.x, v.y, v.z);

        if (targetGate !== 3) {
          targetGate = 3;
          phase = 'pad_glide';
          integralY = 0;
          integralZ = 0;
          integralX = 0;
          pinned = false;
        }

        if (distPad < 0.25) {
          integralX = clamp(integralX + (pad.x - p.x) * dt, -0.25, 0.25);
          integralZ = clamp(integralZ + (pad.z - p.z) * dt, -0.25, 0.25);
        } else {
          integralX *= 0.95;
          integralZ *= 0.95;
        }

        if (phase === 'pad_glide') {
          const glideY = clamp(0.11 + 0.70 * distPad, 0.11, 1.05);
          target = { x: pad.x, y: glideY, z: pad.z };
          kpX = 6.2; kdX = 4.4;
          kpZ = 6.2; kdZ = 4.4;
          kpY = 6.5; kdY = 4.2;
          const closeReady = distPad < 0.12 && speedHoriz < 0.36 && p.y < 0.25;
          const lateReady = obs.t > 13.6 && distPad < 0.14 && speedHoriz < 0.45 && p.y < 0.28;
          if (closeReady || lateReady) {
            phase = 'descend';
            integralY = 0;
          }
        }

        if (phase === 'descend') {
          target = { x: pad.x, y: 0.03, z: pad.z };
          kpX = 6.8; kdX = 4.6;
          kpZ = 6.8; kdZ = 4.6;
          kpY = 6.2; kdY = 4.2;
          integralY = clamp(integralY, -0.2, 0.02);
          if (distPad > 0.142 && p.y > 0.105) {
            phase = 'pad_glide';
          } else if (p.y <= 0.093 && distPad <= 0.144 && speedTotal < 0.48) {
            phase = 'pin';
            pinned = true;
          }
        }

        if (phase === 'pin') {
          target = { x: pad.x, y: 0.0, z: pad.z };
          kpX = 7.5; kdX = 4.5;
          kpZ = 7.5; kdZ = 4.5;
          pinned = true;
          if (distPad > 0.147 && p.y > 0.096) {
            phase = 'pad_glide';
            pinned = false;
          }
        }
