      const vMaxX = clamp(1.45 - 0.12 * Math.max(0, Math.sign(ex) * windFast.x), 0.80, 1.45);
      const vMaxZ = clamp(1.30 - 0.12 * Math.max(0, Math.sign(ez) * windFast.z), 0.72, 1.30);

